from pathlib import Path
P=Path(__file__).parent;C=P/'meridian-deck';E=C/'elements'
def add(e,s):
 p=E/e/'element.css';p.write_text(p.read_text()+'\n/* Pass 2: restore the source badge and circular data vocabulary. */\n'+s.replace('@',f'[data-el="meridian-deck-{e}"]'))
add('card','@.card:has(.mark){padding:var(--gap-lg) var(--pad);border:0;background:none;isolation:isolate}@.card:has(.mark)::before{content:"";position:absolute;z-index:-1;top:calc(var(--gap-lg) + 60px);bottom:var(--gap-lg);left:0;right:0;border-radius:var(--radius);background:var(--n-1);border-top:var(--stroke) solid var(--a1)}@.card.on:has(.mark)::before{background:var(--a1);border-top-color:var(--a1)}@.card.line:has(.mark)::before{background:var(--page);border:var(--stroke) solid var(--a1)}@.card:has(.mark) .parts{height:100%;grid-template-rows:auto auto auto minmax(0,1fr);gap:var(--gap-sm);align-content:stretch}@.card:has(.mark) .mark{align-self:start;width:144px;height:144px;border:var(--rail-w) solid var(--a1);background:var(--page)}@.card:has(.mark) .name{font-size:var(--type-24);padding:var(--gap-sm) 0;min-height:0}@.card:has(.mark) .note{font-size:var(--type-18);padding-top:var(--gap-sm);align-self:start}')
p=E/'card/element.css';p.write_text(p.read_text()+'\n@container (max-height:380px){[data-el="meridian-deck-card"].card:has(.mark){padding:var(--gap-sm) var(--gap-sm)}[data-el="meridian-deck-card"].card:has(.mark) .mark{width:96px;height:96px}[data-el="meridian-deck-card"].card:has(.mark) .note{font-size:var(--type-14)}[data-el="meridian-deck-card"].card:has(.mark) .name{font-size:var(--type-20)}}\n@container (max-width:220px){[data-el="meridian-deck-card"].card:has(.mark) .mark{width:80px;height:80px}[data-el="meridian-deck-card"].card:has(.mark) .note{font-size:var(--type-12)}}')
add('pill','@.pill{flex:0 0 auto;height:auto}@.pill .parts{min-height:var(--gap);height:auto}')
add('prose','@.prose{flex:0 1 auto;height:auto}')
add('chart-donut','@.donut{background:none;border-radius:0;aspect-ratio:auto;width:100%;max-width:100%;height:auto;max-height:100%;min-height:80px;flex:1;isolation:isolate}@.donut::before{position:absolute;inset:auto;left:50%;top:50%;translate:-50% -50%;width:min(100cqw,100cqh,220px);height:min(100cqw,100cqh,220px);background:conic-gradient(var(--a1) calc(var(--v)*1%),var(--n-2) 0);z-index:0}@.donut::after{content:"";position:absolute;left:50%;top:50%;translate:-50% -50%;width:calc(min(100cqw,100cqh,220px) - 28px);height:calc(min(100cqw,100cqh,220px) - 28px);background:var(--page);border-radius:999px;z-index:1}@.donut>.fig,@.donut>.name{z-index:2}@.donuts>.donut{height:100%}')
add('person','@.person>.note{font-size:var(--type-18);line-height:var(--body-line);font-weight:var(--body-weight);border-bottom:0}')
f=C/'foundation/foundation.css';f.write_text(f.read_text()+'\n.slide .page{padding-top:calc(var(--margin-y) + var(--top-h) + var(--gap-sm))}.slide .head{height:var(--top-h)}.slide .cover .page{padding:var(--margin-x)}.slide .cover .lockup.at-center .title{font-size:var(--type-88)}\n')
r=P/'build_reassembled.py';s=r.read_text();s=s.replace("light['--a1']='#0063ed'","light['--page']='#ffffff';light['--ink']='#222222';light['--a1']='#0063ed'")
s=s.replace("f'<b class=\"name\">부서명</b><p class=\"note\">{name}</p>'+ls([note])", "f'<b class=\"name\">부서명</b><p class=\"note\">{name}<br><br>{note}</p>'")
s=s.replace("+str(n).zfill(2)+'</footer>'", "+str(1 if n<=6 else 2 if n<=8 else 3 if n==9 else 4 if n<=13 else 5 if n<=18 else 6 if n<=23 else 7 if n<=27 else 8).zfill(2)+'</footer>'")
r.write_text(s)
print('Visual source vocabulary fixes applied')
